import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import './AccountPage.css';

const RegisterPage = () => {
  const navigate = useNavigate();
  const { register } = useAuth();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const res = await register({ name, email, password });
      if (res) navigate('/account');
    } catch (err) {
      setError(err?.response?.data?.message || 'Registration failed');
    } finally { setLoading(false); }
  };

  return (
    <div className="account-page">
      <header className="account-header"><h1>Create Account</h1></header>
      <div className="account-content">
        <form className="auth-form" onSubmit={handleSubmit}>
          {error && <div className="form-error">{error}</div>}
          <div className="form-group">
            <label>Name</label>
            <input type="text" value={name} onChange={(e)=>setName(e.target.value)} required />
          </div>
          <div className="form-group">
            <label>Email</label>
            <input type="email" value={email} onChange={(e)=>setEmail(e.target.value)} required />
          </div>
          <div className="form-group">
            <label>Password</label>
            <input type="password" value={password} onChange={(e)=>setPassword(e.target.value)} required />
          </div>
          <div className="form-actions">
            <button className="btn btn-primary" disabled={loading}>{loading ? 'Creating...' : 'Create Account'}</button>
            <Link to="/login" className="btn btn-secondary">Already have an account</Link>
          </div>
        </form>
      </div>
    </div>
  );
};

export default RegisterPage;
