import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useCart } from '../context/CartContext';
import { FiArrowLeft, FiTrash2, FiMinus, FiPlus, FiTag } from 'react-icons/fi';
import './CartPage.css';

const CartPage = () => {
  const navigate = useNavigate();
  const { cartItems, addToCart, updateQuantity, removeFromCart, getCartTotal, clearCart } = useCart();

  const frequentlyBought = [
    { id: 'addon-1', name: 'Coca Cola', price: 450.00, image: 'https://images.unsplash.com/photo-1554866585-cd94860890b7?w=400&h=400&fit=crop' },
    { id: 'addon-2', name: 'Vanilla Shake', price: 850.00, image: 'https://images.unsplash.com/photo-1572490122747-3968b75cc699?w=400&h=400&fit=crop' },
    { id: 'addon-3', name: 'Fries', price: 800.00, image: 'https://images.unsplash.com/photo-1573080496219-bb080dd4f877?w=400&h=400&fit=crop' }
  ];

  // Calculate totals dynamically
  const subtotal = getCartTotal();
  const deliveryFee = cartItems.length > 0 ? 200.00 : 0;
  const salesTax = cartItems.length > 0 ? 50.00 : 0;
  const total = subtotal + deliveryFee + salesTax;

  const handleCheckout = () => {
    if (cartItems.length > 0) {
      navigate('/checkout');
    }
  };

  return (
    <div className="cart-page">
      {/* Header */}
      <header className="cart-header">
        <button className="btn btn-icon" onClick={() => navigate('/')}>
          <FiArrowLeft size={24} />
        </button>
        <h1>My Cart ({cartItems.length} items)</h1>
        <button className="btn-text clear-btn" onClick={clearCart}>
          Clear All
        </button>
      </header>

      <div className="cart-content">
        {cartItems.length === 0 ? (
          <div className="empty-cart">
            <div className="empty-icon">🛒</div>
            <h2>Your cart is empty</h2>
            <p>Add some delicious items to get started!</p>
            <button className="btn btn-primary" onClick={() => navigate('/')}>
              Browse Menu
            </button>
          </div>
        ) : (
          <>
            {/* Cart Items */}
            <div className="cart-items">
              {cartItems.map((item) => {
                const apiId = item.cartItemId || item.id;
                return (
                <div key={item.id} className="cart-item">
                  <div className="item-image">
                    {item.image && item.image.startsWith('http') ? (
                      <img src={item.image} alt={item.name} />
                    ) : (
                      <span className="item-emoji">{item.image || '🍽️'}</span>
                    )}
                  </div>
                  <div className="item-details">
                    <h3>{item.name}</h3>
                    {item.description && (
                      <p className="item-description">{item.description}</p>
                    )}
                    {item.size && <p className="item-size">{item.size}</p>}
                    {item.extras && item.extras.length > 0 && (
                      <p className="item-extras">
                        {item.extras.map(e => e.name).join(', ')}
                      </p>
                    )}
                    <div className="item-footer">
                      <span className="item-price">Rs {(item.price * item.quantity).toFixed(2)}</span>
                      <div className="quantity-control">
                        <button 
                          className="qty-btn"
                          onClick={() => updateQuantity(apiId, item.quantity - 1)}
                        >
                          <FiMinus size={16} />
                        </button>
                        <span className="quantity">{item.quantity}</span>
                        <button 
                          className="qty-btn"
                          onClick={() => updateQuantity(apiId, item.quantity + 1)}
                        >
                          <FiPlus size={16} />
                        </button>
                      </div>
                    </div>
                  </div>
                  <button 
                    className="delete-btn"
                    onClick={() => removeFromCart(apiId)}
                  >
                    <FiTrash2 size={18} />
                  </button>
                </div>
              )})}
            </div>

            {/* Frequently Bought Together */}
            <div className="frequently-bought">
              <h3>Frequently bought together</h3>
              <div className="addon-list">
                {frequentlyBought.map((addon) => (
                  <div key={addon.id} className="addon-item">
                    <div className="addon-image">
                      <img src={addon.image} alt={addon.name} />
                    </div>
                    <div className="addon-info">
                      <h4>{addon.name}</h4>
                      <span className="addon-price">Rs {addon.price.toFixed(2)}</span>
                    </div>
                    <button 
                      className="btn-add"
                      onClick={() => addToCart(addon)}
                    >
                      <FiPlus size={16} />
                    </button>
                  </div>
                ))}
              </div>
            </div>

            {/* Voucher Code */}
            <div className="voucher-section">
              <div className="voucher-input">
                <FiTag color="#FF6B35" size={20} />
                <input type="text" placeholder="Enter Voucher Code" />
              </div>
              <button className="btn btn-primary voucher-btn">Apply</button>
            </div>

            {/* Order Summary */}
            <div className="order-summary">
              <div className="summary-row">
                <span>Subtotal</span>
                <span>Rs {subtotal.toFixed(2)}</span>
              </div>
              <div className="summary-row">
                <span>Delivery Fee</span>
                <span>Rs {deliveryFee.toFixed(2)}</span>
              </div>
              <div className="summary-row">
                <span>Sales Tax</span>
                <span>Rs {salesTax.toFixed(2)}</span>
              </div>
              <div className="summary-row total">
                <span>Total</span>
                <span>Rs {total.toFixed(2)}</span>
              </div>
            </div>
          </>
        )}
      </div>

      {/* Checkout Button */}
      {cartItems.length > 0 && (
        <div className="checkout-bar">
          <button 
            className="btn btn-primary checkout-btn"
            onClick={handleCheckout}
          >
            Checkout • Rs {total.toFixed(2)}
          </button>
        </div>
      )}
    </div>
  );
};

export default CartPage;
