import api from '../utils/apiClient';

const productService = {
  getProducts: async (params = {}) => {
    const res = await api.get('/products', { params });
    return res.data;
  },

  getProduct: async (id) => {
    const res = await api.get(`/products/${id}`);
    return res.data;
  }
};

export default productService;
