import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCart } from '../context/CartContext';
import { FiArrowLeft, FiSearch, FiStar, FiHeart, FiShare2 } from 'react-icons/fi';
import './StorePage.css';
import useProducts from '../hooks/useProducts';

const StorePage = () => {
  const navigate = useNavigate();
  const { addToCart } = useCart();
  const [activeFilter, setActiveFilter] = useState('All');

  const filters = ['All', 'Hot', 'Cold Brew', 'Cheapest'];
  const { products } = useProducts();

  const mapProduct = (p) => ({
    id: p._id || p.id,
    name: p.name,
    description: p.description || '',
    price: Number(p.price) || 0,
    rating: p.rating || 4.5,
    time: p.time || '15-20 min',
    image: p.image || 'https://via.placeholder.com/400x300',
    category: p.category || 'Other',
  });

  const menuItems = products && products.length > 0 ? products.map(mapProduct) : [];

  // Filter logic
  const getFilteredItems = () => {
    if (activeFilter === 'All') {
      return menuItems;
    } else if (activeFilter === 'Cheapest') {
      return [...menuItems].sort((a, b) => a.price - b.price);
    } else {
      return menuItems.filter(item => item.category === activeFilter);
    }
  };

  const filteredItems = getFilteredItems();

  return (
    <div className="store-page">
      {/* Header */}
      <header className="store-header">
        <div className="header-bar">
          <button className="btn btn-icon" onClick={() => navigate('/')}>
            <FiArrowLeft size={24} />
          </button>
          <h1>Colombo Branch</h1>
          <div className="header-actions">
            <button className="btn btn-icon">
              <FiShare2 size={20} />
            </button>
            <button className="btn btn-icon">
              <FiHeart size={20} />
            </button>
          </div>
        </div>

        <div className="search-bar">
          <FiSearch size={20} color="#ADADAD" />
          <input type="text" placeholder="Search in menu..." />
        </div>

        <div className="filters">
          {filters.map((filter) => (
            <button
              key={filter}
              className={`filter-btn ${activeFilter === filter ? 'active' : ''}`}
              onClick={() => setActiveFilter(filter)}
            >
              {filter}
            </button>
          ))}
        </div>
      </header>

      {/* Menu List */}
      <div className="menu-list">
        {filteredItems.map((item) => (
          <div 
            key={item.id} 
            className="menu-item"
            onClick={() => navigate(`/product/${item.id}`)}
          >
            <div className="menu-item-image">
              {item.discount && (
                <div className="discount-tag">{item.discount}</div>
              )}
              <img src={item.image} alt={item.name} className="item-image" />
            </div>

            <div className="menu-item-info">
              <div className="item-header">
                <h3>{item.name}</h3>
                {item.popular && (
                  <span className="badge badge-primary">Popular</span>
                )}
              </div>
              
              {item.description && (
                <p className="item-description">{item.description}</p>
              )}

              {item.rating && (
                <div className="item-meta">
                  <span className="rating">
                    <FiStar color="#FFA500" fill="#FFA500" size={14} />
                    {item.rating}
                  </span>
                  {item.time && (
                    <>
                      <span className="separator">•</span>
                      <span className="time">{item.time}</span>
                    </>
                  )}
                  {item.viewCount && (
                    <>
                      <span className="separator">•</span>
                      <span className="views">{item.viewCount}</span>
                    </>
                  )}
                </div>
              )}

              <div className="item-footer">
                <span className="price">Rs {item.price.toFixed(2)}</span>
                <button 
                  className="btn btn-primary btn-sm"
                  onClick={(e) => {
                    e.stopPropagation();
                    addToCart(item);
                  }}
                >
                  Add +
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default StorePage;
