import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import './AccountPage.css';

const LoginPage = () => {
  const navigate = useNavigate();
  const { login } = useAuth();
  const { continueAsGuest } = useAuth();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const res = await login({ email, password });
      if (res) navigate('/account');
    } catch (err) {
      setError(err?.response?.data?.message || 'Login failed');
    } finally { setLoading(false); }
  };

  return (
    <div className="account-page">
      <div style={{ display: 'flex', justifyContent: 'center', padding: '40px 16px' }}>
        <div style={{ width: 480, maxWidth: '96%', background: '#fff', padding: 24, borderRadius: 6, boxShadow: '0 4px 18px rgba(0,0,0,0.06)' }}>
          <header className="account-header" style={{ marginBottom: 8 }}><h1>Sign In</h1></header>
          <div className="account-content">
            <form className="auth-form" onSubmit={handleSubmit}>
              {error && <div className="form-error">{error}</div>}
              <div className="form-group">
                <label>Email</label>
                <input type="email" value={email} onChange={(e)=>setEmail(e.target.value)} required />
              </div>
              <div className="form-group">
                <label>Password</label>
                <input type="password" value={password} onChange={(e)=>setPassword(e.target.value)} required />
              </div>
              <div className="form-actions" style={{ display: 'flex', gap: 8, alignItems: 'center', marginTop: 12 }}>
                <button className="btn btn-primary" disabled={loading}>{loading ? 'Signing in...' : 'Sign In'}</button>
                <Link to="/register" className="btn btn-secondary">Create account</Link>
                <button type="button" className="btn" onClick={() => { continueAsGuest(); window.location.href = '/'; }}>Continue as guest</button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;
