import React, { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useCart } from '../context/CartContext';
import { FiArrowLeft, FiPhone, FiMessageSquare, FiCheck, FiPackage, FiTruck } from 'react-icons/fi';
import './OrderTrackingPage.css';
import { useSocket } from '../context/SocketContext';
import orderService from '../services/orderService';

const OrderTrackingPage = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const { cartItems, getCartTotal } = useCart();
  const { joinOrder, leaveOrder, on } = useSocket();
  const [liveOrder, setLiveOrder] = useState(null);

  // Random driver names
  const driverNames = ['Liyanage', 'Athukorala', 'Vitharana', 'Kannangara'];
  const randomDriver = driverNames[Math.floor(Math.random() * driverNames.length)];

  const orderStatuses = [
    {
      id: 1,
      title: 'Order Confirmed',
      time: '3:15 PM',
      description: 'Your order has been confirmed',
      completed: true,
      icon: <FiCheck size={20} />
    },
    {
      id: 2,
      title: 'Preparing your meal',
      time: '3:25 PM',
      description: 'Chef is cooking your order',
      completed: true,
      icon: <FiPackage size={20} />
    },
    {
      id: 3,
      title: 'Out for Delivery',
      time: '3:35 PM',
      description: 'Driver is on the way',
      completed: false,
      active: true,
      icon: <FiTruck size={20} />
    },
    {
      id: 4,
      title: 'Delivered',
      time: '4:00 PM (Est)',
      description: 'Order will be delivered',
      completed: false,
      icon: <FiCheck size={20} />
    }
  ];

  // Prefer liveOrder items if available
  const orderItems = liveOrder && Array.isArray(liveOrder.items) && liveOrder.items.length > 0
    ? liveOrder.items.map((it) => ({ id: it.product || it._id || it.id, name: it.name || '', quantity: it.quantity || it.qty || 1, price: it.price || 0, image: it.image || '' }))
    : (cartItems.length > 0 ? cartItems : []);

  const subtotal = orderItems.reduce((s, it) => s + (it.price || 0) * (it.quantity || 1), 0);
  const deliveryFee = liveOrder?.deliveryFee ?? (orderItems.length > 0 ? 200.00 : 0);
  const salesTax = subtotal * 0.10;
  const total = subtotal + deliveryFee + salesTax;

  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        const data = await orderService.getOrder(id);
        if (!mounted) return;
        setLiveOrder(data);
      } catch (e) {
        // ignore
      }
    })();

    joinOrder(id);
    const off = on('orderUpdate', (payload) => {
      if (payload && (payload.orderId === id || payload.orderId === payload.orderId?.toString())) {
        setLiveOrder((prev) => ({ ...(prev || {}), ...payload.order }));
      }
    });

    return () => { mounted = false; off && off(); leaveOrder(id); };
  }, [id]);

  return (
    <div className="order-tracking-page">
      {/* Header */}
      <header className="tracking-header">
        <button className="btn btn-icon" onClick={() => navigate('/')}>
          <FiArrowLeft size={24} />
        </button>
        <div className="header-info">
          <h1>Order #{id}</h1>
          <span className="order-badge">ON TIME</span>
        </div>
        <button className="btn-text help-btn">Help</button>
      </header>

      <div className="tracking-content">
        {/* Arrival Info */}
        <div className="arrival-card">
          <div className="arrival-icon">🚚</div>
          <div className="arrival-info">
            <h2>Arriving in 15-20 mins</h2>
            <p>Estimated arrival: 3:45 PM</p>
          </div>
        </div>

        {/* Driver Info */}
        <div className="driver-card">
          <div className="driver-image">👤</div>
          <div className="driver-info">
            <h3>{randomDriver}</h3>
            <p>Your Delivery Plus Driver</p>
            <div className="driver-rating">
              ⭐ 4.9 • 1,234 trips
            </div>
          </div>
          <div className="driver-actions">
            <button className="btn btn-icon contact-btn">
              <FiPhone size={20} />
            </button>
            <button className="btn btn-icon contact-btn">
              <FiMessageSquare size={20} />
            </button>
          </div>
        </div>

        {/* Order Status Timeline */}
        <div className="status-section">
          <h2>Order Status</h2>
          <div className="status-timeline">
            {orderStatuses.map((status, index) => (
              <div 
                key={status.id} 
                className={`status-item ${status.completed ? 'completed' : ''} ${status.active ? 'active' : ''}`}
              >
                <div className="status-icon-wrapper">
                  <div className="status-icon">{status.icon}</div>
                  {index < orderStatuses.length - 1 && <div className="status-line"></div>}
                </div>
                <div className="status-content">
                  <div className="status-header">
                    <h4>{status.title}</h4>
                    <span className="status-time">{status.time}</span>
                  </div>
                  <p className="status-description">{status.description}</p>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Cancel Order */}
        <button className="btn cancel-order-btn">
          Cancel Order
        </button>
      </div>
    </div>
  );
};

export default OrderTrackingPage;
