import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { FiSettings, FiMapPin, FiHeart, FiCreditCard, FiMessageSquare, FiLogOut } from 'react-icons/fi';
import './AccountPage.css';

const AccountPage = () => {
  const { user, logout, isAuthenticated } = useAuth();
  const userData = user || { name: 'Guest User', email: '', phone: '', avatar: '👤' };
  const navigate = useNavigate();

  React.useEffect(() => {
    if (!isAuthenticated) navigate('/login');
  }, [isAuthenticated, navigate]);

  const stats = [
    { label: 'Orders', value: '12', icon: '📦' },
    { label: 'Pending', value: '4', icon: '⏱️' },
    { label: 'Reviews', value: '2', icon: '⭐' }
  ];

  const quickActions = [
    { id: 1, icon: <FiMapPin size={24} />, label: 'My Orders', subtitle: 'Track your orders', color: '#FF6B35', path: '/orders' },
    { id: 2, icon: <FiMapPin size={24} />, label: 'Addresses', subtitle: 'Manage locations', color: '#4CAF50', path: '/account/addresses' },
    { id: 3, icon: <FiHeart size={24} />, label: 'Favorites', subtitle: 'Saved items', color: '#E91E63', path: '/account/favorites' },
    { id: 4, icon: <FiCreditCard size={24} />, label: 'Payment', subtitle: 'Cards & wallet', color: '#2196F3', path: '/account/payment' },
    { id: 5, icon: <FiMessageSquare size={24} />, label: 'Notifications', subtitle: 'Alerts & updates', color: '#9C27B0', path: '/account/notifications' },
    { id: 6, icon: <FiMessageSquare size={24} />, label: 'Help & Support', subtitle: 'Get assistance', color: '#FF9800', path: '/support' }
  ];

  const settings = [
    { id: 1, label: 'Dark Mode', type: 'toggle', value: false },
    { id: 2, label: 'Push Notifications', type: 'toggle', value: true },
    { id: 3, label: 'Language', type: 'select', value: 'English' },
    { id: 4, label: 'Privacy Policy', type: 'link' },
    { id: 5, label: 'Terms & Conditions', type: 'link' }
  ];

  return (
    <div className="account-page">
      {/* Header */}
      <header className="account-header">
        <h1>My Account</h1>
        <button className="btn btn-icon" onClick={() => navigate('/account/settings')}>
          <FiSettings size={24} />
        </button>
      </header>

      <div className="account-content">
        {/* Profile Card */}
        <div className="profile-card">
          <div className="profile-avatar">{userData.avatar || '👤'}</div>
          <div className="profile-info">
            <h2>{userData.name}</h2>
            <p>{userData.email}</p>
            {userData.phone && <p className="profile-phone">{userData.phone}</p>}
          </div>
          <button className="btn btn-secondary edit-profile-btn" onClick={() => navigate('/account/settings')}>
            Edit Profile
          </button>
        </div>

        {/* Stats */}
        <div className="stats-grid">
          {stats.map((stat, index) => (
            <div key={index} className="stat-card">
              <div className="stat-icon">{stat.icon}</div>
              <div className="stat-value">{stat.value}</div>
              <div className="stat-label">{stat.label}</div>
            </div>
          ))}
        </div>

        {/* Quick Actions */}
        <div className="section">
          <h3>Quick Actions</h3>
          <div className="actions-grid">
            {quickActions.map((action) => (
              <div 
                key={action.id} 
                className="action-card"
                onClick={() => action.path ? navigate(action.path) : null}
              >
                <div className="action-icon" style={{ backgroundColor: `${action.color}15`, color: action.color }}>
                  {action.icon}
                </div>
                <div className="action-info">
                  <h4>{action.label}</h4>
                  <p>{action.subtitle}</p>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Preferences */}
        <div className="section">
          <h3>Preferences</h3>
          <div className="settings-list">
            {settings.map((setting) => (
              <div key={setting.id} className="setting-item">
                <div className="setting-info">
                  <span className="setting-label">{setting.label}</span>
                  {setting.type === 'select' && (
                    <span className="setting-value">{setting.value}</span>
                  )}
                </div>
                {setting.type === 'toggle' && (
                  <label className="toggle-switch">
                    <input type="checkbox" defaultChecked={setting.value} />
                    <span className="toggle-slider"></span>
                  </label>
                )}
                {setting.type === 'link' && (
                  <span className="setting-arrow">›</span>
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Sign Out */}
        <button className="btn sign-out-btn" onClick={async () => { await logout(); navigate('/login'); }}>
          <FiLogOut size={20} />
          Sign Out
        </button>
      </div>

      {/* Bottom Navigation */}
      <nav className="bottom-nav">
        <button className="nav-item" onClick={() => navigate('/')}>
          <span className="nav-icon">🏠</span>
          <span className="nav-label">Home</span>
        </button>
        <button className="nav-item" onClick={() => navigate('/store')}>
          <span className="nav-icon">🔍</span>
          <span className="nav-label">Search</span>
        </button>
        <button className="nav-item" onClick={() => navigate('/cart')}>
          <span className="nav-icon">🛍️</span>
          <span className="nav-label">Cart</span>
        </button>
        <button className="nav-item active">
          <span className="nav-icon">👤</span>
          <span className="nav-label">Profile</span>
        </button>
      </nav>
    </div>
  );
};

export default AccountPage;
