import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCart } from '../context/CartContext';
import useProducts from '../hooks/useProducts';
import { FiMenu, FiShoppingBag, FiMapPin, FiSearch, FiStar, FiClock } from 'react-icons/fi';
import './HomePage.css';

const HomePage = () => {
  const navigate = useNavigate();
  const { getCartCount, addToCart } = useCart();
  const [activeCategory, setActiveCategory] = useState('Burgers');
  const [deliveryMethod, setDeliveryMethod] = useState('delivery');
  const [searchQuery, setSearchQuery] = useState('');

  const { products } = useProducts();

  const categories = products && products.length > 0
    ? Array.from(new Set(products.map(p => p.category || 'Other')))
    : [];

  const mapProduct = (p) => ({
    id: p._id || p.id,
    name: p.name,
    description: p.description || '',
    price: Number(p.price) || 0,
    rating: p.rating || 4.5,
    time: p.time || '15-20 min',
    image: p.image || p.imageUrl || 'https://via.placeholder.com/400x300',
    badge: p.badge || '',
    category: p.category || 'Other'
  });

  const menuItemsByCategory = products && products.length > 0
    ? products.reduce((acc, p) => {
        const cat = p.category || 'Other';
        acc[cat] = acc[cat] || [];
        acc[cat].push(mapProduct(p));
        return acc;
      }, {})
    : {};

  // Filter items based on search query
  const getFilteredItems = () => {
    if (!searchQuery.trim()) {
      return menuItemsByCategory[activeCategory] || [];
    }
    
    const allItems = Object.values(menuItemsByCategory).flat();
    return allItems.filter(item => 
      item.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      item.description.toLowerCase().includes(searchQuery.toLowerCase())
    );
  };

  const featuredItems = getFilteredItems();

  const signatures = products && products.length > 0 ? products.slice(0,4).map(mapProduct) : [];

  return (
    <div className="homepage">
      {/* Header */}
      <header className="header">
        <div className="header-top">
          <button className="btn btn-icon">
            <FiMenu size={24} />
          </button>
          <div className="header-location">
            <p className="label">Delivering To</p>
            <div className="location">
              <FiMapPin size={16} color="#FF6B35" />
              <span>Colombo</span>
            </div>
          </div>
          <button className="btn btn-icon cart-btn" onClick={() => navigate('/cart')}>
            <FiShoppingBag size={24} />
            {getCartCount() > 0 && <span className="cart-badge">{getCartCount()}</span>}
          </button>
        </div>

        <div className="search-bar">
          <FiSearch size={20} color="#ADADAD" />
          <input 
            type="text" 
            placeholder="Search for food..." 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </header>

      {/* Hero Banner (uses top product if available) */}
      {products && products.length > 0 && (() => {
        const top = mapProduct(products[0]);
        return (
          <div className="hero-banner">
            <div className="hero-content">
              <div className="hero-image">
                <img src={top.image} alt={top.name} />
              </div>
              <div className="hero-text">
                <h1>{top.name}</h1>
                <p>{top.description}</p>
              </div>
            </div>
            <div className="hero-stats">
              <div className="stat">
                <span className="stat-value">{top.rating}</span>
                <span className="stat-label">Rating</span>
              </div>
              <div className="stat">
                <span className="stat-value">{top.reviews || 0}</span>
                <span className="stat-label">Reviews</span>
              </div>
              <div className="stat">
                <span className="stat-value">Rs {top.price.toFixed(2)}</span>
                <span className="stat-label">Price</span>
              </div>
            </div>
            <div className="hero-actions">
              <button 
                className={`btn ${deliveryMethod === 'delivery' ? 'btn-primary' : 'btn-secondary'}`} 
                style={{ flex: 1 }}
                onClick={() => setDeliveryMethod('delivery')}
              >
                <FiShoppingBag size={18} /> Delivery
              </button>
              <button 
                className={`btn ${deliveryMethod === 'pickup' ? 'btn-primary' : 'btn-secondary'}`} 
                style={{ flex: 1 }}
                onClick={() => setDeliveryMethod('pickup')}
              >
                Pickup
              </button>
            </div>
          </div>
        );
      })()}

      {/* Categories */}
      <div className="categories">
        <button className="btn btn-icon">
          <FiMenu size={20} />
        </button>
        {categories.map((category) => (
          <button
            key={category}
            className={`category-btn ${activeCategory === category ? 'active' : ''}`}
            onClick={() => setActiveCategory(category)}
          >
            {category}
          </button>
        ))}
      </div>

      {/* Featured Items */}
      <section className="section">
        <div className="section-header">
          <h2>Popular Now</h2>
          <button className="btn-text" onClick={() => navigate('/store')}>View All</button>
        </div>
        <div className="food-grid">
          {featuredItems.map((item) => (
            <div 
              key={item.id} 
              className="food-card"
              onClick={() => navigate(`/product/${item.id}`)}
            >
              {item.discount && <div className="discount-badge">{item.discount}</div>}
              {item.badge && <div className="badge">{item.badge}</div>}
              <div className="food-image">
                <img src={item.image} alt={item.name} />
              </div>
              <div className="food-info">
                <h3>{item.name}</h3>
                <p>{item.description}</p>
                <div className="food-meta">
                  <span className="rating">
                    <FiStar color="#FFA500" fill="#FFA500" size={14} />
                    {item.rating}
                  </span>
                  <span className="time">
                    <FiClock size={14} />
                    {item.time}
                  </span>
                </div>
                <div className="food-footer">
                  <span className="price">Rs {item.price.toFixed(2)}</span>
                  <button 
                    className="btn btn-primary btn-icon"
                    onClick={(e) => {
                      e.stopPropagation();
                      addToCart(item);
                    }}
                  >
                    +
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Signatures */}
      <section className="section">
        <h2>Signature</h2>
        <div className="signature-list">
          {signatures.map((item) => (
            <div 
              key={item.id} 
              className="signature-item"
              onClick={() => navigate(`/product/${item.id}`)}
            >
              <div className="signature-image">
                <img src={item.image} alt={item.name} />
              </div>
              <div className="signature-info">
                <h4>{item.name}</h4>
                <span className="price">Rs {item.price.toFixed(2)}</span>
              </div>
              <button 
                className="btn btn-primary btn-icon"
                onClick={(e) => {
                  e.stopPropagation();
                  addToCart(item);
                }}
              >
                +
              </button>
            </div>
          ))}
        </div>
      </section>

      {/* Bottom Navigation */}
      <nav className="bottom-nav">
        <button className="nav-item active">
          <span className="nav-icon">🏠</span>
          <span className="nav-label">Home</span>
        </button>
        <button className="nav-item" onClick={() => navigate('/store')}>
          <span className="nav-icon">🔍</span>
          <span className="nav-label">Search</span>
        </button>
        <button className="nav-item" onClick={() => navigate('/cart')}>
          <span className="nav-icon">🛍️</span>
          <span className="nav-label">Cart</span>
        </button>
        <button className="nav-item" onClick={() => navigate('/account')}>
          <span className="nav-icon">👤</span>
          <span className="nav-label">Profile</span>
        </button>
      </nav>
    </div>
  );
};

export default HomePage;
