import api from '../utils/apiClient';

const orderService = {
  createOrder: async ({ items, addressId, paymentMethod }) => {
    const res = await api.post('/orders', { items, addressId, paymentMethod });
    return res.data;
  },

  getOrders: async () => {
    const res = await api.get('/orders');
    return res.data;
  },

  getOrder: async (orderId) => {
    const res = await api.get(`/orders/${orderId}`);
    return res.data;
  }
};

export default orderService;
